-- keyleader listen shows the which-key panel from Hyprland's submap events.
local keys = require("keys")
hl.bind("ALT + SPACE", hl.dsp.submap("leader"))
hl.define_submap("leader", function()
  for _, mods in ipairs({ "", "ALT + " }) do
    hl.bind(mods .. "SPACE", keys.leave(hl.dsp.exec_cmd("~/.local/bin/keyleader run SPC")))
    hl.bind(mods .. "W", hl.dsp.submap("leader-w"))
    hl.bind(mods .. "B", hl.dsp.submap("leader-b"))
    hl.bind(mods .. "A", hl.dsp.submap("leader-a"))
  end
  hl.bind("escape", hl.dsp.submap("reset"))
  hl.bind("catchall", keys.cancel("leader"))
end)
hl.define_submap("leader-w", function()
  for _, mods in ipairs({ "", "ALT + " }) do
    hl.bind(mods .. "H", keys.leave(hl.dsp.focus({ direction = "left" }), "Alt+Space w h", "Focus left"))
    hl.bind(mods .. "J", keys.leave(hl.dsp.focus({ direction = "down" }), "Alt+Space w j", "Focus down"))
    hl.bind(mods .. "K", keys.leave(hl.dsp.focus({ direction = "up" }), "Alt+Space w k", "Focus up"))
    hl.bind(mods .. "L", keys.leave(hl.dsp.focus({ direction = "right" }), "Alt+Space w l", "Focus right"))
    hl.bind(mods .. "D", keys.leave(hl.dsp.exec_cmd("~/.local/bin/keyleader run w d")))
    hl.bind(mods .. "M", keys.leave(hl.dsp.window.fullscreen({ mode = "maximized" }), "Alt+Space w m", "Maximize or zoom"))
  end
  hl.bind("escape", hl.dsp.submap("reset"))
  hl.bind("catchall", keys.cancel("leader-w"))
end)
hl.define_submap("leader-b", function()
  for _, mods in ipairs({ "", "ALT + " }) do
    hl.bind(mods .. "B", keys.leave(hl.dsp.exec_cmd("~/.local/bin/keyleader run b b")))
    hl.bind(mods .. "N", keys.leave(hl.dsp.window.cycle_next(), "Alt+Space b n", "Next buffer, tab or window"))
    hl.bind(mods .. "P", keys.leave(hl.dsp.window.cycle_next({ next = false }), "Alt+Space b p", "Previous buffer, tab or window"))
  end
  hl.bind("escape", hl.dsp.submap("reset"))
  hl.bind("catchall", keys.cancel("leader-b"))
end)
hl.define_submap("leader-a", function()
  for _, mods in ipairs({ "", "ALT + " }) do
    hl.bind(mods .. "A", keys.leave(hl.dsp.exec_cmd("~/.local/bin/keyleader run a a")))
    hl.bind(mods .. "T", keys.leave(hl.dsp.exec_cmd("~/.local/bin/keyleader run a t")))
    hl.bind(mods .. "B", keys.leave(hl.dsp.focus({ workspace = 2 }), "Alt+Space a b", "Browser workspace"))
    hl.bind(mods .. "I", keys.leave(hl.dsp.focus({ workspace = 4 }), "Alt+Space a i", "IntelliJ workspace"))
  end
  hl.bind("escape", hl.dsp.submap("reset"))
